#!/usr/bin/env python3
from __future__ import annotations
import json,re,sys
from pathlib import Path
BOOK='economics'; BOOK_VERSION='2026.07.27-2'; CANVA_DESIGN_ID='DAHQ5KUGsYE'; CANVA_EDIT_URL='https://www.canva.com/d/MugMiO_8aGO0Myb'; VP_ASSET='assets/economics-svg/ppf.svg'; VP_MARKER='data-vp-asset="economics-shock-curves-equilibrium-welfare-policy-map"'
def nxt(v):
 m=re.fullmatch(r'(\d{4}\.\d{2}\.\d{2})-(\d+)',v); assert m,v; return f'{m.group(1)}-{int(m.group(2))+1}'
def svg_text():
 return '''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 1280" role="img" aria-labelledby="title desc"><title id="title">經濟學原理衝擊曲線均衡福利與政策判斷地圖</title><desc id="desc">從稀少性與機會成本出發，辨認外生衝擊、曲線位移與均衡，再處理彈性福利政策與總體傳導。</desc><rect width="900" height="1280" rx="30" fill="#f4f6fb"/><rect x="34" y="34" width="832" height="184" rx="24" fill="#334155"/><text x="68" y="88" font-size="29" font-weight="700" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#fff">經濟學原理｜衝擊 → 曲線 → 均衡 → 福利 → 政策判斷地圖</text><text x="68" y="136" font-size="16" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#e2e8f0">考題先分沿線移動或曲線位移，再比較新舊均衡；計算只是後半段。</text><text x="68" y="178" font-size="16" font-weight="700" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#cbd5e1">辨題型 → 找外生衝擊 → 移曲線 → 比均衡 → 算福利／彈性 → 回到直覺</text><rect x="42" y="246" width="816" height="218" rx="22" fill="#fff" stroke="#2563eb" stroke-width="3"/><text x="70" y="292" font-size="24" font-weight="700" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#1d4ed8">① 稀少性、PPF 與市場</text><text x="70" y="336" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#1f2937">PPF：曲線上＝有效率；曲線外＝目前不可達；斜率反映機會成本。</text><text x="70" y="374" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#1f2937">機會成本是放棄的最佳替代方案；沉沒成本不應左右未來選擇。</text><text x="70" y="412" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#1f2937">商品本身價格改變通常沿需求／供給曲線移動；所得、成本、預期、技術才使曲線位移。</text><text x="70" y="446" font-size="15" font-weight="700" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#1d4ed8">先判「移動」還是「位移」。</text><rect x="42" y="490" width="816" height="218" rx="22" fill="#fff" stroke="#0f766e" stroke-width="3"/><text x="70" y="536" font-size="24" font-weight="700" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#0f766e">② 供需、彈性與政策</text><text x="70" y="580" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#1f2937">均衡先找 Qd＝Qs，再判價格與數量方向；彈性是比例反應，不等同斜率。</text><text x="70" y="618" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#1f2937">稅、補貼、價格管制先畫 wedge，再談消費者／生產者剩餘與無謂損失。</text><text x="70" y="656" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#1f2937">比較利益看機會成本；正外部性常使市場產量低於社會效率量。</text><text x="70" y="690" font-size="15" font-weight="700" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#0f766e">方向判斷錯，後面算得再準也沒用。</text><rect x="42" y="734" width="816" height="218" rx="22" fill="#fff" stroke="#b45309" stroke-width="3"/><text x="70" y="780" font-size="24" font-weight="700" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#92400e">③ 個體選擇與市場結構</text><text x="70" y="824" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#1f2937">消費者：預算限制＋偏好；生產者：邊際成本與收益。</text><text x="70" y="862" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#1f2937">完全競爭、獨占先固定市場結構，再決定 P、MR、MC 的關係。</text><text x="70" y="900" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#1f2937">外部性題先找私人成本／效益與社會成本／效益的落差，再談政策。</text><text x="70" y="934" font-size="15" font-weight="700" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#92400e">模型選擇先於公式。</text><rect x="42" y="978" width="816" height="198" rx="22" fill="#fff" stroke="#7c3aed" stroke-width="3"/><text x="70" y="1024" font-size="24" font-weight="700" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#6d28d9">④ 總體、貨幣與開放經濟</text><text x="70" y="1068" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#1f2937">GDP、物價、失業是不同指標；財政／貨幣政策先寫傳導鏈，再判產出、物價、利率。</text><text x="70" y="1106" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#1f2937">乘數、貨幣乘數、AD-AS 都是條件式模型，不是普遍實證定律。</text><text x="70" y="1144" font-size="15" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#1f2937">開放經濟分清匯率、淨出口與國際收支基本恆等關係。</text><rect x="42" y="1200" width="816" height="46" rx="16" fill="#1f2937"/><text x="450" y="1230" text-anchor="middle" font-size="15" font-weight="700" font-family="system-ui,'Noto Sans TC','Microsoft JhengHei',sans-serif" fill="#fff">每個結論都要連同假設一起寫；先判機制，再算數字</text></svg>\n'''
def apply(site_root,before):
 site=Path(site_root); lp=site/'data/library.json'; lib=json.loads(lp.read_text(encoding='utf-8')); assert lib['version']==before
 root=site/'books'/BOOK; mp=root/'manifest.json'; m=json.loads(mp.read_text(encoding='utf-8')); assert m['id']==BOOK and m['version']==BOOK_VERSION; changed=False
 fig=f'<figure class="chapter-figure" {VP_MARKER}><a href="{VP_ASSET}" target="_blank" rel="noopener"><img loading="lazy" src="{VP_ASSET}" alt="經濟學原理衝擊曲線均衡福利與政策判斷地圖"></a><figcaption>衝擊 → 曲線 → 均衡 → 福利 → 政策判斷地圖｜點圖可開啟 SVG 大圖放大閱讀。</figcaption></figure>'
 ch=root/'chapters/ch00.html'; t=ch.read_text(encoding='utf-8'); old='<figure><img alt="生產可能線呈現效率、不可達與機會成本遞增" loading="lazy" src="assets/economics-svg/ppf.svg"/><figcaption>生產可能線呈現效率、不可達與機會成本遞增</figcaption></figure>'
 if VP_MARKER not in t:
  assert old in t; ch.write_text(t.replace(old,fig,1),encoding='utf-8'); changed=True
 ap=root/'chapters/appendix-b.html'; t=ap.read_text(encoding='utf-8'); anchor='<h2 id="圖形題六步驟">圖形題六步驟</h2>'
 if VP_MARKER not in t:
  assert anchor in t; ap.write_text(t.replace(anchor,fig+anchor,1),encoding='utf-8'); changed=True
 sp=site/VP_ASSET; sv=svg_text()
 if sp.read_text(encoding='utf-8')!=sv: sp.write_text(sv,encoding='utf-8'); changed=True
 vp={'status':'passed','date':'2026-07-31','asset':VP_ASSET,'placement':'ch00 and appendix-b','canvaDesignId':CANVA_DESIGN_ID,'canvaEditUrl':CANVA_EDIT_URL,'tabletReadable':True,'zoomable':True,'offlineCachedViaExistingAssetPath':True}
 if m.get('visualPolish')!=vp: m['visualPolish']=vp; mp.write_text(json.dumps(m,ensure_ascii=False,indent=2)+'\n',encoding='utf-8'); changed=True
 if changed:
  after=nxt(before); lib['version']=after; lp.write_text(json.dumps(lib,ensure_ascii=False,indent=2)+'\n',encoding='utf-8'); swp=site/'sw.js'; sw=swp.read_text(encoding='utf-8'); sw,n=re.subn(r"const VERSION = 'study-library-[^']+';",f"const VERSION = 'study-library-{after}';",sw,count=1); assert n==1; swp.write_text(sw,encoding='utf-8'); return after
 return before
if __name__=='__main__': print(apply(sys.argv[1],sys.argv[2]))
